#include <bits/stdc++.h>
using namespace std;

long long pow_mod(long long a, long long b, long long mod) {
    long long res = 1;
    while (b > 0) {
        if (b % 2 == 1) {
            res = (res * a) % mod;
            b--;
        }
        a = (a * a) % mod;
        b /= 2;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long N, M, L, R;
    cin >> N >> M >> L >> R;
    long long total_cells = N * M;
    long long range_size = R - L + 1;
    const long long MOD = 998244353;

    if (total_cells % 2 == 1) {
        cout << pow_mod(range_size, total_cells, MOD) << "\n";
    } else if (range_size % 2 == 0) {
        long long result = (pow_mod(range_size, total_cells, MOD) * (MOD + 1) / 2) % MOD;
        cout << result << "\n";
    } else {
        long long result = ((pow_mod(range_size, total_cells, MOD) + 1) * (MOD + 1) / 2) % MOD;
        cout << result << "\n";
    }
    return 0;
}

